import type { TokenStore } from '../auth/tokenStore';

import type { Versioned } from './etag';
import { malformedResponseProblem, networkProblem, problemFromResponse } from './problem';
import type { operations, paths } from './schema';

/**
 * The single way the frontend talks to the API.
 *
 * The *types* come from the contract — `schema.d.ts` is generated by
 * `openapi-typescript` from `var/cache/openapi.bundled.yaml` before every build
 * (`openapi/README.md` section 11). There is no hand-written API module that
 * could drift from the contract; what is hand-written here is the transport,
 * and it is deliberately thin:
 *
 *  - sets `Authorization: Bearer <access token>` from the token store,
 *  - turns every failure into an {@link ApiProblem} carrying the contract's
 *    `code`, the field errors and the `X-Request-Id`,
 *  - answers a `401` with **one** refresh attempt and retries the request once.
 *
 * The refresh is single-flight: ten queries that all come back `401` after a
 * token expires produce one `POST /auth/refresh`, not ten. That is not merely
 * tidy — every refresh token is single-use and a second concurrent exchange
 * would look like a *replayed* token to the server, which revokes the whole
 * family and signs the user out (`auth.refresh_reused`). Bundling is what keeps
 * an ordinary token expiry from tripping the theft detection.
 */

export type HttpMethod = 'get' | 'post' | 'put' | 'patch' | 'delete';

/**
 * The header that says a write took effect in the database but not yet in
 * the mail system (U-59). Its one value today is `pending-configuration-run`:
 * mailing lists are rendered into the aliases file by the configuration
 * management, so a change waits for its next run. A stable keyword, never a
 * sentence — the view translates it (E-16).
 */
const EFFECT_HEADER = 'X-Mailadmin-Effect';

export const PENDING_CONFIGURATION_RUN = 'pending-configuration-run';

/** A response body together with the headers a view acts on. */
export interface Exchange<T> extends Versioned<T> {
  /** `X-Mailadmin-Effect`, verbatim, or `null` when the response had none. */
  readonly effect: string | null;
}

/** `true` when the server said the change waits for the next configuration run. */
export function hasPendingConfigurationRun(exchange: { readonly effect: string | null }): boolean {
  return exchange.effect === PENDING_CONFIGURATION_RUN;
}

type OperationObject = { responses: unknown };

export type OperationAt<P extends keyof paths, M extends HttpMethod> =
  M extends keyof paths[P]
    ? paths[P][M] extends OperationObject
      ? paths[P][M]
      : never
    : never;

/** The paths that actually declare this method. */
export type PathsWith<M extends HttpMethod> = {
  [P in keyof paths]: OperationAt<P, M> extends never ? never : P;
}[keyof paths];

type JsonContent<T> = T extends { content: { 'application/json': infer C } } ? C : never;

type ResponseBodyOf<O> = O extends { responses: infer R }
  ? JsonContent<R[Extract<keyof R, 200 | 201>]>
  : never;

/** `void` for the operations that answer `204`, the parsed body otherwise. */
export type ResultOf<O> = [ResponseBodyOf<O>] extends [never] ? void : ResponseBodyOf<O>;

/**
 * The JSON body an operation takes. A **required** `requestBody` makes `body`
 * mandatory; an **optional** one (`requestBody?:`, e.g. resolving a repair
 * entry with or without a note) makes it optional but still typed — the
 * `| undefined` is what {@link Optional} reads as "may be left out". An
 * operation without a body (`requestBody?: never`) yields `never`.
 */
type RequestBodyOf<O> = O extends { requestBody: infer B }
  ? JsonContent<NonNullable<B>>
  : O extends { requestBody?: infer B }
    ? OptionalJson<JsonContent<NonNullable<B>>>
    : never;

type OptionalJson<T> = [T] extends [never] ? never : T | undefined;

type QueryOf<O> = O extends { parameters: { query?: infer Q } } ? Q : never;
type PathParamsOf<O> = O extends { parameters: { path?: infer P } } ? P : never;

type Optional<K extends string, T> = [T] extends [never]
  ? { [key in K]?: undefined }
  : undefined extends T
    ? { [key in K]?: T }
    : { [key in K]: T };

export type RequestOptions<O> = Optional<'body', RequestBodyOf<O>>
  & Optional<'query', QueryOf<O>>
  & Optional<'pathParams', PathParamsOf<O>>
  & {
    signal?: AbortSignal;
    headers?: Record<string, string>;
    /**
     * Skip the refresh-and-retry dance. Set for the authentication endpoints
     * themselves; nothing else has a reason to.
     */
    withoutRefresh?: boolean;
  };

/**
 * The erased form of {@link RequestOptions}. The public methods keep the typed
 * shape; the transport underneath deals in `unknown`, because it has no
 * business knowing which operation it is carrying.
 */
interface SendOptions {
  body?: unknown;
  query?: Record<string, unknown> | undefined;
  pathParams?: Record<string, unknown> | undefined;
  signal?: AbortSignal | undefined;
  headers?: Record<string, string> | undefined;
  withoutRefresh?: boolean | undefined;
}

export interface ApiClientOptions {
  /**
   * Where the API lives, without a trailing slash. Same origin by construction
   * (architecture 11.1) — the value is a path, never a URL with a host, and the
   * client rejects one so that a misconfiguration cannot send a bearer token to
   * a foreign origin.
   */
  readonly baseUrl: string;
  readonly tokenStore: TokenStore;
  /**
   * Called once when the session is definitively over: the refresh failed, or
   * the server rejected the refreshed token as well. The token has already been
   * cleared when this runs.
   */
  readonly onSessionLost?: () => void;
  readonly fetch?: typeof globalThis.fetch;
  readonly now?: () => number;
}

/** The shape `POST /auth/refresh` answers with. */
type SessionResponse = ResponseBodyOf<operations['refreshSession']>;

/**
 * Query values are scalars by contract — the parameter schemas are strings,
 * integers and enumerations (U-20). Anything else is a programming error, and
 * `[object Object]` in a URL is the least helpful way to find out.
 */
function scalar(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }

  throw new Error(`Query parameters must be scalar; received ${typeof value}.`);
}

function buildUrl(
  baseUrl: string,
  path: string,
  pathParams: Record<string, unknown> | undefined,
  query: Record<string, unknown> | undefined,
): string {
  let resolved = path;

  if (pathParams !== undefined) {
    for (const [name, value] of Object.entries(pathParams)) {
      resolved = resolved.replace(`{${name}}`, encodeURIComponent(String(value)));
    }
  }

  // A template placeholder left in the path would be sent literally and produce
  // a confusing 404. Fail where the mistake is instead.
  const leftover = /\{([^}]+)\}/.exec(resolved);

  if (leftover !== null) {
    throw new Error(`Path parameter "${leftover[1] ?? ''}" was not supplied for ${path}.`);
  }

  const search = new URLSearchParams();

  if (query !== undefined) {
    for (const [name, value] of Object.entries(query)) {
      if (value === undefined || value === null) {
        continue;
      }

      if (Array.isArray(value)) {
        for (const item of value as unknown[]) {
          search.append(name, scalar(item));
        }

        continue;
      }

      search.append(name, scalar(value));
    }
  }

  const queryString = search.toString();

  return `${baseUrl}${resolved}${queryString === '' ? '' : `?${queryString}`}`;
}

async function readBody(response: Response): Promise<unknown> {
  if (response.status === 204 || response.headers.get('Content-Length') === '0') {
    return undefined;
  }

  const contentType = response.headers.get('Content-Type') ?? '';

  if (!contentType.includes('json')) {
    // Not a problem document and not a payload — an HTML error page from a
    // proxy, most likely. The text is not shown; only its absence matters.
    await response.text().catch(() => '');

    return undefined;
  }

  return response.json();
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly tokenStore: TokenStore;
  private readonly onSessionLost: () => void;
  private readonly doFetch: typeof globalThis.fetch;

  /**
   * The in-flight refresh, shared by every request that needs one. `null` when
   * no refresh is running. This field *is* the bundling.
   */
  private refreshInFlight: Promise<boolean> | null = null;

  constructor(options: ApiClientOptions) {
    if (/^[a-z][a-z0-9+.-]*:|^\/\//i.test(options.baseUrl)) {
      throw new Error(
        'The API base must be a same-origin path, not an absolute URL. The access token is only '
        + 'ever sent to this origin (architecture 11.1).',
      );
    }

    this.baseUrl = options.baseUrl.replace(/\/+$/, '');
    this.tokenStore = options.tokenStore;
    this.onSessionLost = options.onSessionLost ?? ((): void => undefined);
    this.doFetch = options.fetch ?? globalThis.fetch.bind(globalThis);
  }

  request<M extends HttpMethod, P extends PathsWith<M>>(
    method: M,
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, M>>] | []
  ): Promise<ResultOf<OperationAt<P, M>>> {
    return this.send(method, path, (options ?? {}) as SendOptions).then(
      (exchange) => exchange.body as ResultOf<OperationAt<P, M>>,
    );
  }

  /**
   * Like {@link request}, but also hands back the response headers a view acts
   * on: the `ETag` (U-19) and `X-Mailadmin-Effect` (U-59). A view that will
   * later change or delete what it shows loads it through this and sends the
   * tag back with `ifMatch()` from `./etag` — the backend answers `428`
   * without it and `412` when someone else was faster. A write sent through
   * this learns whether its effect is delayed (`hasPendingConfigurationRun`).
   */
  requestVersioned<M extends HttpMethod, P extends PathsWith<M>>(
    method: M,
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, M>>] | []
  ): Promise<Exchange<ResultOf<OperationAt<P, M>>>> {
    return this.send(method, path, (options ?? {}) as SendOptions).then((exchange) => ({
      data: exchange.body as ResultOf<OperationAt<P, M>>,
      etag: exchange.headers.get('ETag'),
      effect: exchange.headers.get(EFFECT_HEADER),
    }));
  }

  getVersioned<P extends PathsWith<'get'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'get'>>] | []
  ): Promise<Exchange<ResultOf<OperationAt<P, 'get'>>>> {
    return this.requestVersioned('get', path, ...([options] as [RequestOptions<OperationAt<P, 'get'>>]));
  }

  get<P extends PathsWith<'get'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'get'>>] | []
  ): Promise<ResultOf<OperationAt<P, 'get'>>> {
    return this.request('get', path, ...([options] as [RequestOptions<OperationAt<P, 'get'>>]));
  }

  post<P extends PathsWith<'post'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'post'>>] | []
  ): Promise<ResultOf<OperationAt<P, 'post'>>> {
    return this.request('post', path, ...([options] as [RequestOptions<OperationAt<P, 'post'>>]));
  }

  put<P extends PathsWith<'put'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'put'>>] | []
  ): Promise<ResultOf<OperationAt<P, 'put'>>> {
    return this.request('put', path, ...([options] as [RequestOptions<OperationAt<P, 'put'>>]));
  }

  patch<P extends PathsWith<'patch'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'patch'>>] | []
  ): Promise<ResultOf<OperationAt<P, 'patch'>>> {
    return this.request('patch', path, ...([options] as [RequestOptions<OperationAt<P, 'patch'>>]));
  }

  delete<P extends PathsWith<'delete'>>(
    path: P,
    ...[options]: [RequestOptions<OperationAt<P, 'delete'>>] | []
  ): Promise<ResultOf<OperationAt<P, 'delete'>>> {
    return this.request('delete', path, ...([options] as [RequestOptions<OperationAt<P, 'delete'>>]));
  }

  private async send(
    method: string,
    path: string,
    options: SendOptions,
    isRetry = false,
  ): Promise<{ body: unknown; headers: Headers }> {
    const url = buildUrl(
      this.baseUrl,
      path,
      options.pathParams,
      options.query,
    );

    const headers = new Headers(options.headers ?? {});

    headers.set('Accept', 'application/json, application/problem+json');

    const stored = this.tokenStore.read();

    if (stored !== null) {
      headers.set('Authorization', `Bearer ${stored.token}`);
    }

    const hasBody = options.body !== undefined;

    if (hasBody) {
      headers.set('Content-Type', 'application/json');
    }

    const init: RequestInit = {
      method: method.toUpperCase(),
      headers,
      // Same-origin (architecture 11.1). This is what carries the HttpOnly
      // refresh cookie to `/auth/refresh` and `/auth/logout`, and it must not
      // be widened to `include`: `include` would also send it cross-origin.
      credentials: 'same-origin',
      cache: 'no-store',
      redirect: 'error',
    };

    if (hasBody) {
      init.body = JSON.stringify(options.body);
    }

    if (options.signal !== undefined) {
      init.signal = options.signal;
    }

    let response: Response;

    try {
      response = await this.doFetch(url, init);
    } catch (cause) {
      if (cause instanceof DOMException && cause.name === 'AbortError') {
        throw cause;
      }

      throw networkProblem(cause);
    }

    if (response.status === 401 && !isRetry && options.withoutRefresh !== true) {
      const refreshed = await this.refresh();

      if (refreshed) {
        return this.send(method, path, options, true);
      }
    }

    if (!response.ok) {
      let body: unknown;

      try {
        body = await readBody(response);
      } catch {
        body = undefined;
      }

      const problem = problemFromResponse(response.status, body, response.headers);

      if (problem.isUnauthenticated) {
        // Either the refresh failed or it succeeded and the new token was
        // rejected too. Both mean: this session is over.
        this.endSessionLocally();
      }

      throw problem;
    }

    try {
      return { body: await readBody(response), headers: response.headers };
    } catch (cause) {
      throw malformedResponseProblem(response.status, response.headers, cause);
    }
  }

  /**
   * One refresh at a time, whatever the number of callers.
   *
   * Resolves `true` when a new access token was stored. Resolves `false` — it
   * never rejects — when the session is over, because every caller then takes
   * the same path: report the original failure to the user.
   */
  private refresh(): Promise<boolean> {
    this.refreshInFlight ??= this.performRefresh().finally(() => {
      this.refreshInFlight = null;
    });

    return this.refreshInFlight;
  }

  private async performRefresh(): Promise<boolean> {
    let session: SessionResponse;

    try {
      // An empty object, not an empty body: `POST /auth/refresh` rejects a
      // body-less request with `422`, because request validation has to be told
      // what kind of body it is looking at (U-9, and the operation says so).
      // The refresh token itself travels in the cookie and is never touched
      // here — that is the whole point of E-15.
      session = (await this.send('post', '/auth/refresh', {
        body: {},
        withoutRefresh: true,
      })).body as SessionResponse;
    } catch {
      this.endSessionLocally();

      return false;
    }

    if (typeof session?.access_token !== 'string' || typeof session.expires_in !== 'number') {
      this.endSessionLocally();

      return false;
    }

    this.tokenStore.write(session.access_token, session.expires_in);

    return true;
  }

  /**
   * Drops the local half of the session. The cookie half is the server's to
   * expire, and `POST /auth/logout` asks it to.
   */
  private endSessionLocally(): void {
    if (this.tokenStore.read() === null) {
      // Already gone — do not fire the callback a second time for every request
      // that was in flight when the session ended.
      return;
    }

    this.tokenStore.clear();
    this.onSessionLost();
  }
}

/**
 * The API base for this deployment.
 *
 * `import.meta.env.BASE_URL` is what Vite was built with (`/`, or `/mailadmin/`
 * when the project sits in a subdirectory of the web root — U-25 variant B).
 * Deriving the API path from it means the deployment configures one value and
 * both halves follow.
 */
export function defaultApiBaseUrl(): string {
  const base = import.meta.env.BASE_URL;

  return `${base.replace(/\/+$/, '')}/api/v1`;
}
